fn solve(a: i8, b: i8) -> (i8, i8) {
    // We want x and y such that:
    //   a = x + y
    //   b = x - y
    // Solving these gives:
    //   x = (a + b) / 2
    //   y = (a - b) / 2
    //
    // Since a, b ∈ [-100, 100], a±b ∈ [-200, 200], so we do the intermediate
    // arithmetic in i16 to avoid overflow, then cast back to i8.

    let sum = (a as i16 + b as i16) / 2;
    let diff = (a as i16 - b as i16) / 2;
    (sum as i8, diff as i8)
}